"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { createConnection } from "@/lib/api";
import { useToast } from "@/components/ui/Toast";
import AppHeader from "@/components/AppHeader";
import GradientOrbs from "@/components/GradientOrbs";
import Magnetic from "@/components/Magnetic";

export default function ConnectPage() {
  const [form, setForm] = useState({
    nickname: "",
    engine_type: "postgresql" as "postgresql" | "mysql",
    host: "",
    port: 5432,
    database_name: "",
    username: "",
    password: "",
  });
  const [status, setStatus] = useState<"idle" | "testing" | "success">("idle");
  const [error, setError] = useState("");
  const router = useRouter();
  const toast = useToast();

  function update(field: string, value: string | number) {
    setForm((prev) => ({ ...prev, [field]: value }));
  }

  async function handleSubmit() {
    setStatus("testing");
    setError("");
    try {
      await createConnection(form);
      setStatus("success");
      toast("Database connected successfully", "success");
      setTimeout(() => router.push("/home"), 900);
    } catch (err) {
      setStatus("idle");
      const msg = err instanceof Error ? err.message : "Connection failed";
      setError(msg);
      toast(msg, "error");
    }
  }

  const inputClass =
    "rounded-2xl border border-white/10 bg-black/20 px-4 py-3 text-ink placeholder:text-mist/50 transition-all duration-200 focus:border-gold/50 focus:outline-none focus:ring-4 focus:ring-gold/10";
  const labelClass = "text-xs font-medium uppercase tracking-wide text-mist";

  return (
    <main className="relative min-h-screen bg-graphite">
      <GradientOrbs />
      <AppHeader />

      <div className="relative z-10 mx-auto max-w-lg px-6 py-14">
        <div className="animate-fade-in-up mb-8">
          <p className="mb-1 font-mono text-xs uppercase tracking-[0.3em] text-gold">New connection</p>
          <h1 className="font-display text-3xl font-extrabold text-ink">Connect a database</h1>
        </div>

        <div className="animate-spring-in flex flex-col gap-4 rounded-3xl border border-white/10 bg-surface/60 p-7 backdrop-blur-xl">
          <div className="flex flex-col gap-1.5">
            <label className={labelClass}>Nickname</label>
            <input
              placeholder="e.g. My Sales DB"
              className={inputClass}
              value={form.nickname}
              onChange={(e) => update("nickname", e.target.value)}
            />
          </div>

          <div className="flex flex-col gap-1.5">
            <label className={labelClass}>Engine</label>
            <div className="flex gap-2">
              {(["postgresql", "mysql"] as const).map((engine) => (
                <button
                  key={engine}
                  type="button"
                  onClick={() => update("engine_type", engine)}
                  className={`flex-1 cursor-pointer rounded-2xl border px-4 py-3 text-sm font-medium capitalize transition-all duration-200 ${
                    form.engine_type === engine
                      ? "border-gold/50 bg-gradient-to-r from-gold/20 to-violet/20 text-ink"
                      : "border-white/10 bg-black/20 text-mist hover:text-ink"
                  }`}
                >
                  {engine}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <div className="col-span-2 flex flex-col gap-1.5">
              <label className={labelClass}>Host</label>
              <input
                placeholder="localhost"
                className={inputClass}
                value={form.host}
                onChange={(e) => update("host", e.target.value)}
              />
            </div>
            <div className="flex flex-col gap-1.5">
              <label className={labelClass}>Port</label>
              <input
                type="number"
                className={inputClass}
                value={form.port}
                onChange={(e) => update("port", Number(e.target.value))}
              />
            </div>
          </div>

          <div className="flex flex-col gap-1.5">
            <label className={labelClass}>Database name</label>
            <input
              className={inputClass}
              value={form.database_name}
              onChange={(e) => update("database_name", e.target.value)}
            />
          </div>

          <div className="flex flex-col gap-1.5">
            <label className={labelClass}>Username</label>
            <input
              className={inputClass}
              value={form.username}
              onChange={(e) => update("username", e.target.value)}
            />
          </div>

          <div className="flex flex-col gap-1.5">
            <label className={labelClass}>Password</label>
            <input
              type="password"
              className={inputClass}
              value={form.password}
              onChange={(e) => update("password", e.target.value)}
            />
          </div>

          <Magnetic strength={35}>
            <button
              onClick={handleSubmit}
              disabled={status === "testing" || status === "success"}
              className="mt-2 flex w-full cursor-pointer items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-gold to-violet px-4 py-3.5 font-display font-bold text-graphite shadow-[0_15px_40px_-12px_rgba(139,92,246,0.5)] transition-all duration-200 hover:-translate-y-0.5 active:scale-95 disabled:cursor-not-allowed disabled:hover:translate-y-0"
            >
              {status === "testing" && (
                <>
                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-graphite/30 border-t-graphite" />
                  Testing connection...
                </>
              )}
              {status === "success" && (
                <>
                  <span className="animate-success-burst">✓</span>
                  Connected!
                </>
              )}
              {status === "idle" && "Test & save connection"}
            </button>
          </Magnetic>

          {error && (
            <p className="animate-fade-in-up rounded-xl border border-red-500/20 bg-red-500/10 px-3 py-2 text-sm text-red-300">
              {error}
            </p>
          )}
        </div>
      </div>
    </main>
  );
}
